            ['Jade Tubes', 'neon-jade-tubes', '#05060d', '.bg-template-neon-jade-tubes{position:fixed;inset:0;z-index:-1;background-color:#05060d;background-image:radial-gradient(ellipse 90% 70% at 50% 50%, rgba(16,185,129,0.22) 0%, transparent 72%),repeating-linear-gradient(180deg, rgba(110,231,183,0) 0 52px, rgba(110,231,183,0.10) 52px 58px, rgba(110,231,183,0.78) 58px 60px, rgba(110,231,183,0.10) 60px 66px, rgba(110,231,183,0) 66px 124px);}'],
            ['Jade Halo', 'neon-jade-halo', '#05060d', '.bg-template-neon-jade-halo{position:fixed;inset:0;z-index:-1;background-color:#05060d;background-image:repeating-linear-gradient(180deg, rgba(0,0,0,0.34) 0 2px, transparent 2px 4px),radial-gradient(circle at 50% 40%, rgba(110,231,183,0.80) 0%, rgba(110,231,183,0.26) 17%, rgba(16,185,129,0.10) 34%, transparent 58%),linear-gradient(180deg, #0a0714 0%, #05060d 100%);}'],
        ];

        $sort = 100;
        foreach ($rows as [$name, $slug, $preview, $css]) {
            BgTemplate::updateOrCreate(
                ['slug' => $slug],
                [
                    'name'          => $name,
                    'preview_color' => $preview,
                    'css'           => $css,
                    'js'            => null,
                    'category'      => 'neon',
                    'is_active'     => true,
                    'sort_order'    => $sort++,
                ]
            );
        }
    }
}
